items.text:
set hfile [ replace_extension $filename "cs" ]
set fhandle [ open_output_file $hfile ]
catch {
	p.print_to_file $fhandle $functions \
		$methods \
		$header $class $class_name $footer \
		$machines
} error_message
set details $::errorInfo
catch { close $fhandle }

set keywords { 
	public private protected internal
	override abstract static virtual
	method ctr
}

array set props { 
	access none 
	dispatch normal
	type method
}
set error_message ""
set parameters {}
set returns ""
set type "method"

set state "none"
set constants {}
set names {}
set i 1
